const firebaseConfig ={apiKey:"AIzaSyDGLhQPxQx8v2zN5KJ4mYhE9YvLqZwXxYY",authDomain:"rvr-green-port-city.firebaseapp.com",projectId:"rvr-green-port-city",storageBucket:"rvr-green-port-city.firebasestorage.app",messagingSenderId:"123456789",appId:"1:123456789:web:abcdef123456"};firebase.initializeApp(firebaseConfig);const db = firebase.firestore();db.enablePersistence({synchronizeTabs:true}).then(()=>{console.log('✅ Offline persistence enabled - App works completely offline!');showNotification('App ready for offline use','success');}).catch((err)=>{if(err.code === 'failed-precondition'){console.warn('⚠️ Multiple tabs open,persistence only in first tab');}else if(err.code === 'unimplemented'){console.warn('⚠️ Browser doesn\'t support offline persistence');}});let isOnline = navigator.onLine;window.addEventListener('online',()=>{isOnline = true;showNotification('Back online - Syncing data...','success');updateSyncStatus('syncing');});window.addEventListener('offline',()=>{isOnline = false;showNotification('You\'re offline - Data will sync when online','info');updateSyncStatus('offline');});db.onSnapshotsInSync(()=>{if(isOnline){updateSyncStatus('synced');}});function updateSyncStatus(status){const indicator = document.getElementById('syncIndicator');if(!indicator)return;indicator.style.display = 'block';switch(status){case 'synced':indicator.innerHTML = '🟢 Synced';indicator.style.background = '#10b981';setTimeout(()=> indicator.style.display = 'none',3000);break;case 'offline':indicator.innerHTML = '🔴 Offline';indicator.style.background = '#ef4444';break;case 'syncing':indicator.innerHTML = '🟡 Syncing...';indicator.style.background = '#f59e0b';break;}}function showNotification(message,type){console.log(`[${type.toUpperCase()}] ${message}`);}function submitEnquiryOffline(event){event.preventDefault();const formData = new FormData(event.target);const data ={...Object.fromEntries(formData),timestamp:firebase.firestore.FieldValue.serverTimestamp(),status:'new',submittedAt:new Date().toISOString(),offline:!navigator.onLine};const submitBtn = event.target.querySelector('button[type="submit"]');const originalText = submitBtn ? submitBtn.textContent:'Submit Enquiry';if(submitBtn){submitBtn.disabled = true;submitBtn.textContent = isOnline ? 'Submitting...':'Saving offline...';}db.collection('enquiries').add(data).then((docRef)=>{console.log('✅ Enquiry saved:',docRef.id,isOnline ? '(online)':'(offline - will sync)');if(submitBtn){submitBtn.textContent = isOnline ? 'Submitted! ✓':'Saved! Will sync ✓';submitBtn.style.background = '#10b981';}setTimeout(()=>{const message = isOnline ? 'Thank you! Your enquiry has been submitted. Our team will contact you within 30 minutes.':'Enquiry saved offline! It will be automatically sent when you\'re back online.';alert(message);event.target.reset();if(submitBtn){submitBtn.disabled = false;submitBtn.textContent = originalText;submitBtn.style.background = '';}if(typeof closeNewMenu === 'function')closeNewMenu();},1500);}).catch((error)=>{console.error('❌ Error saving enquiry:',error);if(submitBtn){submitBtn.disabled = false;submitBtn.textContent = originalText;}alert('Error submitting enquiry. Please try again.');});}